  RAISE EXCEPTION 'Esta OS jÃ¡ foi encerrada.';
 END IF;
 IF p_status IN ('em_andamento','pronta','finalizada') AND p_approval<>'aprovado' THEN RAISE EXCEPTION 'Aprove o orÃ§amento antes de avanÃ§ar.'; END IF;
