CREATE OR REPLACE FUNCTION partner_subscription_private.require_access(p_company uuid, p_feature text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE s jsonb;
BEGIN
 s:=partner_subscription_private.state(p_company);
 IF NOT COALESCE((s->>'can_access')::boolean,false) THEN RAISE EXCEPTION 'Assinatura sem acesso ativo. Regularize em Configurações ou fale com o administrador.'; END IF;
 IF NOT (s->'features' ? p_feature) THEN RAISE EXCEPTION 'Este recurso não está incluído no plano contratado.'; END IF;
END;
$function$

CREATE OR REPLACE FUNCTION partner_subscription_private.require_actor(p_feature text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE company uuid;
BEGIN PERFORM partner_subscription_private.require_collaborator_module(p_feature);
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Não autenticado.'; END IF;
 IF public.is_super_admin() THEN RETURN; END IF;
 SELECT id INTO company FROM public.partner_profiles WHERE id=auth.uid();
 IF company IS NULL THEN SELECT user_id INTO company FROM public.partner_salespeople
  WHERE auth_user_id=auth.uid() AND active=true LIMIT 1; END IF;
 IF company IS NULL THEN RAISE EXCEPTION 'Empresa não autorizada.'; END IF;
 PERFORM partner_subscription_private.require_access(company,p_feature);
END;
$function$

CREATE OR REPLACE FUNCTION partner_operations_private.authorize_branch(p_branch uuid, p_feature text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE company uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'NÃ£o autenticado.'; END IF;
 SELECT user_id INTO company FROM public.partner_branches WHERE id=p_branch AND is_active;
 IF company IS NULL OR NOT (company=auth.uid() OR public.partner_employee_can_access_branch(company,p_branch) OR public.is_super_admin()) THEN
  RAISE EXCEPTION 'Filial nÃ£o autorizada.';
 END IF;
 PERFORM partner_subscription_private.require_actor(p_feature);
 PERFORM partner_subscription_private.require_access(company,p_feature);
 RETURN company;
END $function$
